data.value:
Select ProductionHeader.DocumentNo, ProductionItem.Description AS ItemName, ProductionRack.RackName, ProductionDocument.DocumentType, ProductionDocument.MenuID, ProductionMenu.MenuPath, ProductionLocation.LocationName AS GoDown, ProductionDetail.TransactionQuantity AS Quantity, ProductionDocument.TransactionImpact, ProductionHeader.DocumentDate from INV_StockTransactionHeader as ProductionHeader inner join INV_StockTransactionDetail ProductionDetail on ProductionDetail.StockTransactionID = ProductionHeader.StockTransactionID and ProductionDetail.CompanyID = ProductionHeader.CompanyID and ProductionDetail.PeriodID = ProductionHeader.PeriodID And ProductionDetail.Status = 1 inner join SET_Location AS ProductionLocation on ProductionLocation.LocationID = ProductionDetail.LocationID inner join INV_Item As ProductionItem on ProductionItem.ItemID = ProductionDetail.ItemID --and ProductionItem.CompanyID = ProductionDetail.CompanyID left join SET_Rack As ProductionRack on ProductionRack.RackID = ProductionDetail.RackID inner join SET_DocumentType As ProductionDocument on ProductionDocument.DocumentTypeID = ProductionHeader.DocumentTypeID and ProductionDocument.CompanyID = ProductionHeader.CompanyID and ProductionDocument.PeriodID = ProductionHeader.PeriodID inner join ApplicationMenu As ProductionMenu on ProductionMenu.MenuID = ProductionDocument.MenuID And ProductionMenu.MenuPath like '/Inventory/Transaction/FinishedGoods.aspx%' Where ProductionHeader.CompanyID = @CompanyID And ProductionHeader.PeriodID = @PeriodID AND ProductionDocument.TransactionImpact <> 'No Impact' {0}{2}{4}
Union all
Select SupplyHeader.DocumentNo, SupplyItem.Description, SupplyRack.RackName, SupplyDocument.DocumentType,SupplyDocument.MenuID, SupplyMenu.MenuPath, SupplyLocation.LocationName, SupplyDetail.TransactionQuantity AS Quantity, SupplyDocument.TransactionImpact, SupplyHeader.DocumentDate from INV_StockTransactionHeader as SupplyHeader inner join INV_StockTransactionDetail SupplyDetail on SupplyDetail.StockTransactionID = SupplyHeader.StockTransactionID and SupplyDetail.CompanyID = SupplyHeader.CompanyID and SupplyDetail.PeriodID = SupplyHeader.PeriodID And SupplyDetail.Status = 1 inner join SET_Location AS SupplyLocation on SupplyLocation.LocationID = SupplyDetail.LocationID inner join INV_Item As SupplyItem on SupplyItem.ItemID = SupplyDetail.ItemID --and SupplyItem.CompanyID = SupplyDetail.CompanyID left join SET_Rack As SupplyRack on SupplyRack.RackID = SupplyDetail.RackID inner join SET_DocumentType As SupplyDocument on SupplyDocument.DocumentTypeID = SupplyHeader.DocumentTypeID and SupplyDocument.CompanyID = SupplyHeader.CompanyID and SupplyDocument.PeriodID = SupplyHeader.PeriodID inner join ApplicationMenu As SupplyMenu on SupplyMenu.MenuID = SupplyDocument.MenuID And SupplyMenu.MenuPath like '/Sales/Dispatch_frm.aspx%' Where SupplyHeader.CompanyID = @CompanyID And SupplyHeader.PeriodID = @PeriodID AND SupplyDocument.TransactionImpact <> 'No Impact' {1}{3}{5}
